        }
        std::cin >> word >> target;
        ladder.push_back(word);
        bool found = false;
        int past_size = -1;
        while (!found) {
            found = wordLadder(word, target, wordBank, ladder);
            if (found) {
                break;
            } else {
                if (past_size == ladder.size()) {
                    std::cout << "Solution Does Not Exist\n";
                    break;
                }
