void Queue::enqueue(int data) {
    Node *newNode = new Node;
    newNode->data = data;
    newNode->next = nullptr;
    if (front == nullptr) {
        front = newNode;
        rear = newNode;
    } else {
        rear->next = newNode;
        rear = newNode;
    }
}

int Queue::dequeue() {
    if (front == nullptr) {
        cout << "The Queue is empty" << endl;
        return -1;
    } else {
        Node *temp = front;
        int data = temp->data;
        front = front->next;
        delete temp;
        return data;
    }
}

