                            onStackFlag[w] = false;
                            resSubData[w] = nrParts;
                        } while (w != v);
                        nrParts++;
                    }
                    stack.pop_back();
                }
            }
        }
    }
}

void strongConnectIterative(const std::vector<NodeType>& node1Data, const std::vector<NodeType>& node2Data, const std::vector<LinkType>& link1, const std::vector<LinkType>& nextLink1, std::vector<Couple<NodeType>>& indices, NodeType& currIndex, sequence_traits<Bool>::container_type& onStackFlag, NodeStackType& nodeStack, std::vector<PartType>& resSubData, PartType& nrParts) {
    struct Frame {
        NodeType node;
        LinkType currentLink;
        bool processSuccessor;
    };
    std::vector<Frame> stack;
    for (NodeType startNode = 0; startNode < node1Data.size(); ++startNode) {
        if (!IsDefined(indices[startNode].first)) {
            indices[startNode] = {currIndex, currIndex};
            ++currIndex;
            nodeStack.push_back(startNode);
            onStackFlag[startNode] = true;
            stack.push_back({startNode, link1[startNode], false});
            while (!stack.empty()) {
                auto& frame = stack.back();
                auto& v = frame.node;
                auto& currentLink = frame.currentLink;
                auto& processSuccessor = frame.processSuccessor;
                if (processSuccessor) {
                    NodeType w = node2Data[currentLink];
                    indices[v].second = std::min(indices[v].second, indices[w].second);
                    processSuccessor = false;
                }
                CHECK_CURRENT_LINK:
                if (IsDefined(currentLink)) {
                    NodeType w = node2Data[currentLink];
                    if (!IsDefined(indices[w].first)) {
                        processSuccessor = true;
                        stack.push_back({w, link1[w], false});
                        continue;
                    } else {
                        if (onStackFlag[w]) {
                            indices[v].second = std::min(indices[v].second, indices[w].first);
                        }
                        currentLink = nextLink1[currentLink];
                        goto CHECK_CURRENT_LINK;
                    }
                } else {
                    if (indices[v].first == indices[v].second) {
                        NodeType w;
                        do {
                            w = nodeStack.back(); nodeStack.pop_back();
                            onStackFlag[w] = false;
                            resSubData[w] = nrParts;
                        } while (w != v);
                        nrParts++;
                    }
                    stack.pop_back();
                }
            }
        }
    }
}

void workerFunction()
{
    proj_context* projCtx;
    {
        std::lock_guard<std::mutex> lock(projMutex);
        projCtx = proj_context_create();
    }
    CPLSetThreadLocalConfigOption("OGR_ENABLE_PARTIAL_REPROJECTION", "YES");
    CPLSetThreadLocalConfigOption("OGR_ENABLE_PARTIAL_REPROJECTION_THREADS", "YES");
    CPLSetThreadLocalConfigOption("PROJ_THREAD_SAFE", "YES");
    OGRRegisterAll();
    OGRSpatialReference sourceSRS;
    OGRSpatialReference targetSRS;
    sourceSRS.importFromEPSG(4326);
    targetSRS.importFromEPSG(3857);
    OGRCoordinateTransformation* transformation = OGRCreateCoordinateTransformation(&sourceSRS, &targetSRS);
    OGRCoordinateTransformation::DestroyCT(transformation);
    {
        std::lock_guard<std::mutex> lock(projMutex);
        proj_context_destroy(projCtx);
    }
}

int main()
{
    int numThreads = 4;
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i)
    {
        threads.emplace_back(workerFunction);
    }
    for (std::thread& thread : threads)
    {
        thread.join();
    }
    return 0;
}

int GetMonitorScaleFactor(HWND hWnd)
{
    HDC hdc = GetDC(hWnd);
    int logPixelsX = GetDeviceCaps(hdc, LOGPIXELSX);
    ReleaseDC(hWnd, hdc);
    if (logPixelsX == 96)
        return 100;
    else if (logPixelsX == 120)
        return 125;
    else if (logPixelsX == 144)
        return 150;
    else if (logPixelsX == 192)
        return 200;
    return 0;
}

