    int shmidB = shmget(IPC_PRIVATE, N*N*sizeof(int), IPC_CREAT | 0666);
    int shmidC = shmget(IPC_PRIVATE, N*N*sizeof(int), IPC_CREAT | 0666);
    int *shm_A = shmat(shmidA, NULL, 0);
    int *shm_B = shmat(shmidB, NULL, 0);
