int main(int argc, char *argv[]) {
    int N = 0, verbose = 0, numProcessors = 2;
    getCommands(argc, argv, &N, &verbose, &numProcessors);
    int **A, **B, **C;
    allocateMatrices(&A, &B, &C, N);
    fillMatrices(A, B, C, N);
    int rowsPerProcessor = N / numProcessors;
    int pipefd[numProcessors][2];
    for (int i = 0; i < numProcessors; i++) {
        if (pipe(pipefd[i]) == -1) {
            perror("pipe");
            exit(EXIT_FAILURE);
        }
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            close(pipefd[i][0]);
            int startRow = i * rowsPerProcessor;
            int endRow = (i + 1) * rowsPerProcessor;
            if (i == numProcessors - 1) endRow = N;
            int *resultChunk = (int *)malloc(rowsPerProcessor * N * sizeof(int));
            multiplyChunk(A, B, resultChunk, N, startRow, endRow);
            write(pipefd[i][1], resultChunk, rowsPerProcessor * N * sizeof(int));
            close(pipefd[i][1]);
            free(resultChunk);
            exit(0);
        }
        close(pipefd[i][1]);
    }
    for (int i = 0; i < numProcessors; i++) {
        int startRow = i * rowsPerProcessor;
        int endRow = (i + 1) * rowsPerProcessor;
        if (i == numProcessors - 1) endRow = N;
        read(pipefd[i][0], &C[startRow][0], (endRow - startRow) * N * sizeof(int));
        close(pipefd[i][0]);
        wait(NULL);
    }
    if (verbose) {
        printMatrices(A, B, C, N);
        printf("Time Clock to process: %f", cpu_time_used);
    } else {
        printf("%d, %f\n", N, cpu_time_used);
    }
    freeMatrices(A, B, C, N);
    return 0;
}

void multiplyChunk(int **A, int **B, int *resultChunk, int N, int startRow, int endRow) {
    int idx = 0;
    for (int i = startRow; i < endRow; i++) {
        for (int j = 0; j < N; j++) {
            int sum = 0;
            for (int k = 0; k < N; k++) {
                sum += A[i][k] * B[k][j];
            }
            resultChunk[idx++] = sum;
        }
    }
}

void allocateSharedMatrix(int *shmid, int N) {
    *shmid = shmget(IPC_PRIVATE, N * N * sizeof(int), IPC_CREAT | 0666);
    if (*shmid < 0) {
        perror("shmget");
        exit(1);
    }
}

int** attachMatrix(int shmid, int N) {
    int *data = (int *)shmat(shmid, NULL, 0);
    if (data == (int *)-1) {
        perror("shmat");
        exit(1);
    }
    int **matrix = (int **)malloc(N * sizeof(int *));
    for (int i = 0; i < N; i++) {
        matrix[i] = data + N * i;
    }
    return matrix;
}

void detachMatrix(int **matrix) {
    shmdt(*matrix);
    free(matrix);
}

void fillMatrix(int **matrix, int N, int isRandom) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] = isRandom ? rand() % 100 : 0;
        }
    }
}

void multiplyMatrixChunk(int **A, int **B, int **C, int N, int startRow, int endRow) {
    for (int i = startRow; i < endRow; i++) {
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <N> [-p num_processors]\n", argv[0]);
        exit(1);
    }
    int N = atoi(argv[1]);
    srand(time(NULL));
    int shmidA, shmidB, shmidC;
    allocateSharedMatrix(&shmidA, N);
    allocateSharedMatrix(&shmidB, N);
    allocateSharedMatrix(&shmidC, N);
    int **A = attachMatrix(shmidA, N);
    int **B = attachMatrix(shmidB, N);
    int **C = attachMatrix(shmidC, N);
    fillMatrix(A, N, 1);
    fillMatrix(B, N, 1);
    fillMatrix(C, N, 0);
    int numProcessors = MAX_PROCESSORS;
    int rowsPerProcessor = N / numProcessors;
    for (int p = 0; p < numProcessors; p++) {
        int startRow = p * rowsPerProcessor;
        int endRow = (p + 1) * rowsPerProcessor;
        if (p == numProcessors - 1) {
            endRow = N;
        }
        pid_t pid = fork();
        if (pid == 0) {
            multiplyMatrixChunk(A, B, C, N, startRow, endRow);
            detachMatrix(A);
            detachMatrix(B);
            detachMatrix(C);
            exit(0);
        }
    }
    while (wait(NULL) > 0);
    detachMatrix(A);
    detachMatrix(B);
    detachMatrix(C);
    shmctl(shmidA, IPC_RMID, NULL);
    shmctl(shmidB, IPC_RMID, NULL);
    shmctl(shmidC, IPC_RMID, NULL);
    return 0;
}

