void Wire_readRegister(uint8_t i2caddr, uint8_t regaddr, uint8_t *data, uint8_t bytes) {
    uint8_t status;
    I2C_Start();
    status = I2C_SendByte((i2caddr << 1) | 0x00);
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }
    status = I2C_SendByte(regaddr);
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }
    I2C_Start();
    status = I2C_SendByte((i2caddr << 1) | 0x01);
    if (status != I2C_ACK) {
        I2C_Stop();
        return;
    }
    while (bytes > 0) {
        if (bytes == 1) {
            *data = I2C_RecvByte(I2C_NACK);
        } else {
            *data = I2C_RecvByte(I2C_ACK);
        }
        data++;
        bytes--;
    }
    I2C_Stop();
}

void Wire_readRegister(uint8_t i2caddr, uint8_t regaddr, uint8_t *data, uint8_t bytes) {
    uint8_t ack_bit;
    I2CStart();
    ack_bit = I2CSend((i2caddr << 1) | 0);
    if (ack_bit != 0) {
        I2CStop();
        return;
    }
    ack_bit = I2CSend(regaddr);
    if (ack_bit != 0) {
        I2CStop();
        return;
    }
    I2CRestart();
    ack_bit = I2CSend((i2caddr << 1) | 1);
    if (ack_bit != 0) {
        I2CStop();
        return;
    }
    for (uint8_t i = 0; i < bytes; i++) {
        data[i] = I2CRead();
        if (i == (bytes - 1)) {
            I2CNak();
        } else {
            I2CAck();
        }
    }
    I2CStop();
}

