CGEventRef tapCallback(CGEventTapProxy proxy, CGEventType type, CGEventRef event, void* refcon) {
    double now = CFAbsoluteTimeGetCurrent();
    if (type == kCGEventRightMouseDown) {
        rightClickDown = now;
