        kCGEventTapOptionDefault, mask, tapCallback, nullptr);
    if (!eventTap) {
        std::cerr << "Failed to create event tap." << std::endl;
        return 1;
    }
    CFRunLoopSourceRef runLoopSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, eventTap, 0);
