std::pair<int, int> findSumSwapPair(std::vector<int>& arr1, std::vector<int>& arr2) {
    int sum1 = 0, sum2 = 0;
    for (int num : arr1) {
        sum1 += num;
    }
    for (int num : arr2) {
        sum2 += num;
    }
    int targetDifference = (sum1 - sum2) / 2;
    std::unordered_set<int> setArr2(arr2.begin(), arr2.end());
    for (int num : arr1) {
        int complement = num - targetDifference;
        if (setArr2.find(complement) != setArr2.end()) {
            return {num, complement};
        }
    }
    return {-1, -1};
}

int main() {
    std::vector<int> arr1 = {4, 1, 2, 1, 1, 2};
    std::vector<int> arr2 = {3, 6, 3, 3};
    std::pair<int, int> result = findSumSwapPair(arr1, arr2);
    if (result.first != -1 && result.second != -1) {
        std::cout << "Output: {" << result.first << ", " << result.second << "}\n";
    } else {
        std::cout << "No such pair found.\n";
    }
    return 0;
}

void initialize(Stack* stack) {
    stack->top = -1;
}

bool is_empty(Stack* stack) {
    return stack->top == -1;
}

bool is_full(Stack* stack) {
    return stack->top == MAX_SIZE - 1;
}

void push(Stack* stack, char symbol) {
    if (is_full(stack)) {
        printf("Stack overflow!\n");
        exit(1);
    }
    stack->stack[++stack->top] = symbol;
}

char pop(Stack* stack) {
    if (is_empty(stack)) {
        printf("Stack underflow!\n");
        exit(1);
    }
    return stack->stack[stack->top--];
}

bool is_balanced(const char* expression) {
    Stack stack;
    initialize(&stack);
    const char* opening_symbols = "([{";
    const char* closing_symbols = ")]}";
    for (int i = 0; expression[i] != '\0'; i++) {
        char symbol = expression[i];
        if (strchr(opening_symbols, symbol) != NULL) {
            push(&stack, symbol);
        } else if (strchr(closing_symbols, symbol) != NULL) {
            if (is_empty(&stack)) {
                return false;
            }
            char opening_symbol = pop(&stack);
            const char* matching_opening_symbol = strchr(opening_symbols, opening_symbol);
            const char* matching_closing_symbol = strchr(closing_symbols, symbol);
            if (matching_opening_symbol - opening_symbols != matching_closing_symbol - closing_symbols) {
                return false;
            }
        }
    }
    return is_empty(&stack);
}

int main() {
    printf("%d\n", is_balanced("()"));
    printf("%d\n", is_balanced("({[]})"));
    printf("%d\n", is_balanced("({)}"));
    printf("%d\n", is_balanced("[[[]]]"));
    printf("%d\n", is_balanced("(]"));
    return 0;
}

