    double distances[m->nr_nodes];
    int predecessors[m->nr_nodes];
    bool visited[m->nr_nodes];
    for(int i = 0; i < m->nr_nodes; i++) {
        distances[i] = DBL_MAX;
        predecessors[i] = -1;
        visited[i] = false;
    }
    distances[start_id] = 0;
    MinHeap *heap = create_min_heap(m->nr_nodes);
    min_heap_insert(heap, start_id, 0);
