template<typename Iterator>
Iterator find_begin(Iterator begin, Iterator end) {
    while (begin != end && std::isspace(*begin)) {
        ++begin;
    }
    return begin;
}

template<typename Iterator>
Iterator find_end(Iterator begin, Iterator end) {
    while (begin != end && std::isspace(*(end - 1))) {
        --end;
    }
    return end;
}

int main() {
    std::string str = "   Hello, world!   ";
    auto begin = find_begin(str.begin(), str.end());
    auto end = find_end(str.begin(), str.end());
    for (auto it = begin; it != end; ++it) {
        std::cout << *it;
    }
    std::cout << std::endl;
    return 0;
}

template<typename Iterator>
Iterator find_begin(Iterator begin, Iterator end) {
    return std::find_if_not(begin, end, [](char c) { return std::isspace(c); });
}

template<typename Iterator>
Iterator find_end(Iterator begin, Iterator end) {
    return std::find_if_not(std::make_reverse_iterator(end), std::make_reverse_iterator(begin), [](char c) { return std::isspace(c); }).base();
}

int main() {
    std::string text = "   Hello, world!   ";
    auto begin = find_begin(text.begin(), text.end());
    auto end = find_end(text.begin(), text.end());
    std::string stripped_text(begin, end);
    std::cout << "Stripped text: '" << stripped_text << "'" << std::endl;
    return 0;
}

