void ssh_crypto_init() {
    if (!gcry_check_version(GCRYPT_VERSION)) {
        fprintf(stderr, "Libgcrypt version mismatch\n");
        exit(2);
    }
    gcry_control(GCRYCTL_SUSPEND_SECMEM_WARN);
    gcry_control(GCRYCTL_INIT_SECMEM, 16384, 0);
    gcry_control(GCRYCTL_RESUME_SECMEM_WARN);
    gcry_control(GCRYCTL_INITIALIZATION_FINISHED, 0);
}

int decrypt_ssh_payload(const guchar *encrypted_data, guint encrypted_data_len, guchar **decrypted_data, guint *decrypted_data_len) {
    if (encrypted_data == NULL || encrypted_data_len <= 0) {
        return 0;
    }
    const char *key = "your_key_here";
    const char *iv = "your_iv_here";
    size_t blklen = gcry_cipher_get_algo_blklen(GCRY_CIPHER_AES128);
    *decrypted_data_len = encrypted_data_len;
    *decrypted_data = (guchar *)malloc(*decrypted_data_len);
    if (*decrypted_data == NULL) {
        return 0;
    }
    gcry_cipher_hd_t hd;
    gcry_error_t err = gcry_cipher_open(&hd, GCRY_CIPHER_AES128, GCRY_CIPHER_MODE_CBC, 0);
    if (err) {
        free(*decrypted_data);
        return 0;
    }
    err = gcry_cipher_setkey(hd, key, blklen);
    if (err) {
        gcry_cipher_close(hd);
        free(*decrypted_data);
        return 0;
    }
    err = gcry_cipher_setiv(hd, iv, blklen);
    if (err) {
        gcry_cipher_close(hd);
        free(*decrypted_data);
        return 0;
    }
    err = gcry_cipher_decrypt(hd, *decrypted_data, *decrypted_data_len, encrypted_data, encrypted_data_len);
    gcry_cipher_close(hd);
    if (err) {
        free(*decrypted_data);
        return 0;
    }
    return 1;
}

int load_ssh_private_key(const char *filename, gcry_sexp_t *key) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open key file: %s\n", filename);
        return 0;
    }
    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *filecontent = (char *)malloc(filesize + 1);
    if (filecontent == NULL) {
        fclose(fp);
        fprintf(stderr, "Failed to allocate memory for key file\n");
        return 0;
    }
    fread(filecontent, 1, filesize, fp);
    filecontent[filesize] = '\0';
    fclose(fp);
    gcry_error_t err = gcry_sexp_new(key, filecontent, filesize, 0);
    free(filecontent);
    if (err) {
        fprintf(stderr, "Failed to load private key: %s\n", gcry_strerror(err));
        return 0;
    }
    return 1;
}

char* format_with_commas(int num) {
    char buffer[50];
    sprintf(buffer, "%d", num);
    int length = strlen(buffer);
    int commaCount = (length - 1) / 3;
    int finalLength = length + commaCount;
    char *result = malloc(finalLength + 1);
    if (result == NULL) {
        return NULL;
    }
    int i = length - 1, j = finalLength;
    result[j--] = '\0';
    int commaPosition = 3;
    while (i >= 0) {
        result[j--] = buffer[i--];
        commaPosition--;
        if (commaPosition == 0 && j > 0) {
            result[j--] = ',';
            commaPosition = 3;
        }
    }
    return result;
}

int main() {
    int num = 7000000;
    char *formattedNum = format_with_commas(num);
    if (formattedNum) {
        printf("%s\n", formattedNum);
        free(formattedNum);
    } else {
        printf("Memory allocation failed.\n");
    }
    return 0;
}

